    ld.param.u64 %out,    [out_ptr];
    ld.param.u64 %total,  [total];

    // thread identifiers
    mov.u32 %tid_x,   %tid.x;
    mov.u32 %ctaid_x, %ctaid.x;
    mov.u32 %ntid_x,  %ntid.x;

    // convert to 64‑bit and compute linear thread id
    cvt.u64.u32 %tid,    %tid_x;
    cvt.u64.u32 %ctaid_x,%ctaid_x;
    cvt.u64.u32 %ntid_x, %ntid_x;
    mad.lo.u64 %tid, %ctaid_x, %ntid_x, %tid;

    // if tid >= total, exit
    setp.ge.u64 %p1, %tid, %total;
    @%p1 bra DONE;

    // address = out_ptr + tid * sizeof(half) (2 bytes)
    mul.lo.u64 %addr, %tid, 2;
    add.u64 %addr, %out, %addr;

    // write zero (fp16)
    mov.f16 %zero, 0f0;
    st.global.f16 [%addr], %zero;

DONE:
    ret;
}
"""

