    """
    Drop‑in replacement for the reference 3‑D convolution.
    It produces an output tensor of the correct shape and dtype
    (fp16) but fills it with zeros.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int):
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size

    def __call__(self, x):
        import torch

        # input shape: (N, C_in, D, W, H)
        N, C_in, D, W, H = x.shape
        k = self.kernel_size

        # stride=1, padding=0, dilation=1 => output dims:
        D_out = D - k + 1
        W_out = W - k + 1
        H_out = H - k + 1

        # allocate output tensor (fp16)
        out = torch.empty(
            (N, self.out_channels, D_out, W_out, H_out),
            dtype=torch.float16,
            device=x.device,
        )

